private fun updateOnScreenPad() {
    if (hqGameSession()) {
        onScreenControls?.let { it.releaseAll(); it.visibility = View.GONE }
        steamTouchControls?.let { it.releaseAll(); it.visibility = View.GONE }
        com.droiddeck.launcher.input.SteamTouchDevice.current?.plugged = false
        updateHqTouchControls()
        onScreenButtonsVisible = hqTouchControls?.visibility == View.VISIBLE
        return
    }
    hqTouchControls?.visibility = View.GONE

private fun hqGameSession() = com.droiddeck.launcher.hq.RuntimeRules.hqGameControls(
    intent.getBooleanExtra("hqInstallSession", false),
    intent.getStringExtra(SessionService.EXTRA_STEAM_URL), SessionState.steamUrl)

private fun updateHqTouchControls() {
    val controls = hqTouchControls ?: return
    controls.setGameVersion(intent.getIntExtra("hqGameVersion", -1))
    controls.refreshPointerMode()
    controls.visibility = if (hqGameSession() && !pipUi && unfoldedPanel == null &&
        !drawerOpen && !pcKeyboardOpen && !achievementsOpen && !SessionState.suspended) View.VISIBLE else View.GONE
}

